<script setup>
import { ref } from "vue";
const props = defineProps({ profile: Object, saving: Boolean, saved: Boolean, pdfStatus: String, pdfError: String, extractingPdf: Boolean });
const emit = defineEmits(["save", "next", "import-pdf"]);
const mode = ref("choose"), pdf = ref(null), photo = ref(null);
const add = (key, value) => props.profile[key].push(value);
const remove = (key, index) => props.profile[key].splice(index, 1);
function setPhoto(file) { if (!file) return; if (file.size > 2 * 1024 * 1024) return; const reader = new FileReader(); reader.onload = () => { props.profile.photo = reader.result; }; reader.readAsDataURL(file); }
function importPdf(file) { emit("import-pdf", file); mode.value = "manual"; }
</script>

<template>
  <section class="screen">
    <header class="screen-heading"><div><p class="eyebrow">ETAPA 1 DE 4 · PERFIL LOCAL</p><h1>Construa seu perfil profissional.</h1><p>Seus dados ficam neste navegador. Use PDF para acelerar ou preencha cada parte manualmente.</p></div><q-btn flat no-caps icon="save" color="primary" :label="saving ? 'Salvando…' : saved ? 'Salvo localmente' : 'Salvar rascunho'" @click="emit('save')" /></header>
    <div v-if="mode === 'choose'" class="choice-grid"><button class="choice-card" type="button" @click="mode = 'upload'"><q-icon name="upload_file"/><strong>Importar currículo</strong><span>Selecione um PDF; o texto será extraído localmente para revisão.</span></button><button class="choice-card" type="button" @click="mode = 'manual'"><q-icon name="edit_note"/><strong>Preencher manualmente</strong><span>Cadastre formação, carreira, skills, idiomas e projetos.</span></button></div>
    <template v-else-if="mode === 'upload'"><div class="upload-card"><q-icon name="picture_as_pdf"/><div><h2>Selecione o seu currículo em PDF</h2><p>PDF com texto selecionável, até 10 MB. Nenhum arquivo é enviado para o Tailor Match.</p><q-file v-model="pdf" outlined accept="application/pdf,.pdf" label="Escolher arquivo PDF" :loading="extractingPdf" @update:model-value="importPdf"><template #prepend><q-icon name="upload_file"/></template></q-file></div></div><q-banner v-if="pdfError" class="notice error" role="alert">{{ pdfError }} Você pode tentar outro arquivo ou preencher manualmente.</q-banner><q-btn flat no-caps label="Preencher manualmente" @click="mode = 'manual'" /></template>
    <template v-else><q-banner v-if="pdfStatus" class="notice success" role="status">{{ pdfStatus }}</q-banner><section class="form-section"><h2>Identidade</h2><div class="identity-grid"><q-avatar size="96px" color="deep-purple-1" text-color="primary"><img v-if="profile.photo" :src="profile.photo" alt="Foto do perfil"/><q-icon v-else name="person"/></q-avatar><div><q-file v-model="photo" dense outlined accept="image/png,image/jpeg" label="Foto opcional" hint="PNG ou JPG, até 2 MB" @update:model-value="setPhoto"/><q-btn v-if="profile.photo" flat dense color="negative" label="Remover foto" @click="profile.photo = ''"/></div><q-input v-model.trim="profile.name" outlined label="Nome"/><q-input v-model.trim="profile.headline" outlined label="Título profissional"/><q-input v-model.trim="profile.location" outlined label="Localização / modelo de trabalho"/><q-input v-model.trim="profile.links" outlined label="LinkedIn, portfólio ou GitHub"/></div></section>
      <section class="form-section"><div class="section-title"><h2>Idiomas</h2><q-btn flat dense no-caps color="primary" icon="add" label="Adicionar" @click="add('languages', { name: '', level: '' })"/></div><div v-for="(item, index) in profile.languages" :key="index" class="repeat-row"><q-input v-model.trim="item.name" outlined label="Idioma"/><q-input v-model.trim="item.level" outlined label="Nível comprovado"/><q-btn flat round color="negative" icon="delete" aria-label="Remover idioma" @click="remove('languages', index)"/></div></section>
      <section class="form-section"><div class="section-title"><h2>Formação</h2><q-btn flat dense no-caps color="primary" icon="add" label="Adicionar" @click="add('education', { institution: '', course: '', start: '', end: '', status: '', evidence: '' })"/></div><div v-for="(item, index) in profile.education" :key="index" class="repeat-card"><div class="repeat-row"><q-input v-model.trim="item.institution" outlined label="Instituição"/><q-input v-model.trim="item.course" outlined label="Curso"/><q-btn flat round color="negative" icon="delete" aria-label="Remover formação" @click="remove('education', index)"/></div><div class="repeat-row"><q-input v-model.trim="item.start" outlined label="Início"/><q-input v-model.trim="item.end" outlined label="Conclusão"/><q-input v-model.trim="item.status" outlined label="Status"/></div></div></section>
      <section class="form-section"><div class="section-title"><h2>Carreira</h2><q-btn flat dense no-caps color="primary" icon="add" label="Adicionar experiência" @click="add('career', { company: '', role: '', start: '', end: '', responsibilities: '', outcomes: '', technologies: '' })"/></div><div v-for="(item, index) in profile.career" :key="index" class="repeat-card"><div class="repeat-row"><q-input v-model.trim="item.company" outlined label="Empresa"/><q-input v-model.trim="item.role" outlined label="Cargo"/><q-btn flat round color="negative" icon="delete" aria-label="Remover experiência" @click="remove('career', index)"/></div><div class="repeat-row"><q-input v-model.trim="item.start" outlined label="Início"/><q-input v-model.trim="item.end" outlined label="Fim / atual"/></div><q-input v-model="item.responsibilities" type="textarea" autogrow outlined label="Responsabilidades confirmadas"/><q-input v-model="item.outcomes" type="textarea" autogrow outlined label="Resultados comprovados"/><q-input v-model.trim="item.technologies" outlined label="Tecnologias / competências"/></div></section>
      <section class="form-section"><div class="section-title"><h2>Skills e projetos</h2><q-btn flat dense no-caps color="primary" icon="add" label="Adicionar skill" @click="add('skills', { name: '', category: '', evidence: '' })"/></div><div v-for="(item, index) in profile.skills" :key="index" class="repeat-row"><q-input v-model.trim="item.name" outlined label="Skill"/><q-input v-model.trim="item.category" outlined label="Categoria"/><q-input v-model.trim="item.evidence" outlined label="Evidência"/><q-btn flat round color="negative" icon="delete" aria-label="Remover skill" @click="remove('skills', index)"/></div><q-input v-model="profile.confirmedEvidence" type="textarea" autogrow outlined label="Evidências adicionais confirmadas" hint="Use para experiências que não entram nos blocos acima."/><q-input v-model="profile.rawStories" type="textarea" autogrow outlined label="Histórias e anedotas (contexto bruto)" hint="Nunca viram afirmações automaticamente."/></section>
      <footer class="screen-actions"><span>Foto, PDF e perfil ficam locais.</span><q-btn unelevated no-caps color="primary" label="Salvar perfil e continuar" icon-right="arrow_forward" @click="emit('next')"/></footer></template>
  </section>
</template>
